        "code": "class PipelineCoordinator:\n    def __init__(self):\n        self.inv = OutboxSagaWorker(\"inv\", 10)\n        self.pay = OutboxSagaWorker(\"pay\", 200)\n        self.ship_allow = False\n        self.orch_wal = []\n\n    def execute_checkout(self, saga_id, qty, cost, simulate_cdc_dup=True):\n        self.orch_wal.append((saga_id, \"START\"))\n        r1 = self.inv.execute_step(f\"{saga_id}:inv:fwd\", saga_id, -qty)\n        if not r1[\"ok\"]:\n            self.orch_wal.append((saga_id, \"ABORT_EARLY\"))\n            return \"ABORTED\", {\"inv\": self.inv.balance, \"pay\": self.pay.balance}\n        self.orch_wal.append((saga_id, \"STEP1_OK\"))\n\n        r2 = self.pay.execute_step(f\"{saga_id}:pay:fwd\", saga_id, -cost)\n        if not r2[\"ok\"] or not self.ship_allow:\n            self.orch_wal.append((saga_id, \"COMPENSATING\"))\n            # Compensate Payment (and simulate CDC crash duplicate redelivery!)\n            self.pay.execute_step(f\"{saga_id}:pay:comp\", saga_id, +cost, is_compensate=True)\n            if simulate_cdc_dup:\n                self.pay.execute_step(f\"{saga_id}:pay:comp\", saga_id, +cost, is_compensate=True)\n            self.inv.execute_step(f\"{saga_id}:inv:comp\", saga_id, +qty, is_compensate=True)\n            self.orch_wal.append((saga_id, \"COMPENSATED_ABORT\"))\n            return \"COMPENSATED_ABORT\", {\"inv\": self.inv.balance, \"pay\": self.pay.balance}\n        self.orch_wal.append((saga_id, \"COMPLETED\"))\n        return \"COMPLETED\", {\"inv\": self.inv.balance, \"pay\": self.pay.balance}\n\nclass OutboxSagaWorker:\n    def __init__(self, name, bal):\n        self.name, self.balance = name, bal\n        self.dedup, self.tombstones = {}, set()\n    def execute_step(self, key, agg, delta, is_compensate=False):\n        if key in self.dedup: return self.dedup[key]\n        if not is_compensate and agg in self.tombstones:\n            res = {\"ok\": False}; self.dedup[key] = res; return res\n        if self.balance + delta < 0:\n            res = {\"ok\": False}\n        else:\n            self.balance += delta\n            if is_compensate: self.tombstones.add(agg)\n            res = {\"ok\": True, \"bal\": self.balance}\n        self.dedup[key] = res; return res\n\ncoord = PipelineCoordinator()\nstatus, bals = coord.execute_checkout(\"saga-501\", qty=3, cost=75, simulate_cdc_dup=True)\nprint(\"status:\", status, \"restored exact balances:\", bals)\nprint(\"wal trace:\", coord.orch_wal)",
